{"cards": [{"node_code": "N_48c89bca0184971c", "definition": "研究利用锚杆、锚索及喷射混凝土对岩土体进行加固与支护的技术体系，涵盖锚固机理、设计计算、施工工艺及组合支护形式。", "boundary": "本节点聚焦于主动加固与支护手段，包括锚杆/索的受力分析、注浆工艺、格构梁配合及喷锚支护系统。边界涵盖边坡、基坑及隧道等场景下的锚固技术应用。不包含被动挡土结构（如重力式挡墙）的设计，也不包含岩土体本身的力学参数测定。", "includes": ["锚杆与锚索的设计、施工及受力机理", "喷射混凝土与喷锚支护技术", "格构锚固及多种支护形式的组合应用"], "excludes": ["重力式、悬臂式等被动挡土结构的设计（归入重力式与柔性挡土结构）", "板桩、地下连续墙等深层支护结构（归入板桩、地下连续墙与土钉墙）"], "sibling_distinctions": [{"other_code": "N_a039c79419446e20", "rule": "本节点侧重主动锚固与加固（如锚杆、喷锚），兄弟节点侧重被动抵抗土压力的结构（如挡墙）。"}, {"other_code": "N_04f548ed4ea07f2e", "rule": "本节点侧重岩土体内部的锚固与表面喷射支护，兄弟节点侧重插入土体或岩体的板桩、连续墙及土钉等深层或浅层支护结构。"}], "cross_boundary_rule": "涉及锚杆/索在边坡或基坑中的具体应用，主挂载于本节点；若涉及锚固材料的力学性能或岩土体本构关系，可关联岩石力学或土力学节点。"}, {"node_code": "N_a8f7ad96a18dbf6f", "definition": "研究土质边坡在自重、外力及水文作用下保持稳定的分析方法，涵盖极限平衡、数值模拟及可靠性评估等理论与技术。", "boundary": "本节点聚焦于土坡（非岩坡）的稳定性评价，包括滑动面搜索、安全系数计算及影响因素分析。边界涵盖条分法、强度折减法、圆弧滑动分析及概率分析等。不包含岩质边坡的块体理论分析，也不包含边坡加固措施的设计。", "includes": ["土坡稳定性的极限平衡分析方法（条分法、圆弧滑动）", "强度折减法及数值模拟在土坡稳定中的应用", "土坡稳定性的概率分析与可靠性评估"], "excludes": ["岩质边坡的块体理论、结构面分析（归入岩质边坡稳定分析）", "边坡加固、防护及排水措施的设计（归入边坡防护、排水与加固）"], "sibling_distinctions": [{"other_code": "N_ca73eb5917fbba79", "rule": "本节点侧重土体介质的连续介质力学分析（如条分法），兄弟节点侧重岩体介质的结构面控制与块体理论分析。"}], "cross_boundary_rule": "涉及土质边坡的稳定计算，主挂载于本节点；涉及岩质边坡，主挂载于岩质边坡稳定分析；若涉及加固措施，主挂载于边坡防护、排水与加固。"}, {"node_code": "N_c261899cff5e1312", "definition": "研究土体对挡土结构作用力的理论体系，涵盖静止、主动及被动土压力的计算模型、影响因素及工程应用。", "boundary": "本节点聚焦于土压力理论本身，包括朗肯、库仑等经典理论及分层土、超载等复杂条件下的修正。边界涵盖土压力分布规律、合力计算及作用点确定。不包含挡土结构的具体结构设计，也不包含土体本身的物理力学性质测定。", "includes": ["朗肯与库仑土压力理论及其适用条件", "分层土、超载及地下水影响下的土压力计算", "静止、主动及被动土压力的工程应用"], "excludes": ["挡土结构（如挡墙、板桩）的结构设计与配筋（归入重力式与柔性挡土结构或板桩、地下连续墙与土钉墙）", "土体物理力学性质试验与本构模型（归入土力学与土的工程性质）"], "sibling_distinctions": [{"other_code": "N_a039c79419446e20", "rule": "本节点侧重土压力的理论计算与分布规律，兄弟节点侧重基于土压力结果进行挡土结构的设计与构造。"}], "cross_boundary_rule": "涉及土压力计算理论与方法，主挂载于本节点；涉及挡土结构的具体设计，主挂载于重力式与柔性挡土结构或板桩、地下连续墙与土钉墙。"}]}
